import {textSteps} from './text-evidence-core.js?v=20261027motion';
import {spatialLessons} from './spatial-lessons.js?v=20261027motion';
import {detectVisualEffects} from './visual-effects.js?v=20261027motion';
import {detectTemporalEffects} from './temporal-effects.js?v=20261027motion';
export function buildEffectAudit(samples,shots,{text=null,audio=false,spatial=null,short=null}={}){const visual=shots.flatMap(s=>detectVisualEffects(samples,s)),temporalBase=detectTemporalEffects(samples),temporal=short?[...temporalBase.filter(e=>e.end<short.start||e.start>short.end),...detectTemporalEffects(short.samples)]:temporalBase,space=spatialLessons(spatial);return[
 {name:'转场',status:visual.some(e=>e.kind.startsWith('fade'))||temporal.some(e=>e.kind==='flash')?'有候选':'待确认',evidence:[...visual.filter(e=>e.kind.startsWith('fade')),...temporal.filter(e=>e.kind==='flash')],limit:'亮度线索不能区分所有叠化、遮挡、运镜和插件转场。'},
 {name:'变速 / 定格',status:temporal.some(e=>e.kind==='freeze')?'有候选':'待确认',evidence:temporal.filter(e=>e.kind==='freeze'),limit:'仅检查静止区间；没有原始素材帧率和运动基准，不能还原变速曲线。'},
 {name:'字幕动画',status:text?text.pendingResume?'保留上次结果，本次待继续':text.partial?'部分完成，有待续查':text.tracks.length?'有文字证据':'已运行，待确认':'尚未运行',evidence:(text?.tracks||[]).map(t=>({start:t.start,end:t.end,title:'文字试做：'+t.text,preview:{kind:'text',text:t.text,keyframes:t.keyframes},reason:'OCR 实测文字与几何变化；招牌、水印和运镜也可能产生轨迹。',parameters:[t.positionPattern,t.scalePattern].filter(Boolean).join('；')||'已读取文字；尚未得到可靠动画轨迹',steps:textSteps(t)})),limit:text?`${text.partial?'本次基础文字检查仅完成 '+text.completedFrames+'/'+text.plannedFrames+' 个计划采样点；未完成时间未知。':''}OCR ${text.frames.length} 帧，${text.tracks.length} 条文字候选；比较全程位置与尺寸变化，原字体、动画预设和精确入出点未知。${!text.partial&&text.fullScan===false?'仅检查 '+text.coverage.map(r=>r.start.toFixed(2)+'–'+r.end.toFixed(2)+' 秒').join('；')+'，其余时间未知。':''}`:'点击“识别画面文字”检查文字内容与位置变化；不是语音识别。'},
 {name:'蒙版',status:space.mask.length?'有候选':spatial?'已检查，待确认':'尚未运行',evidence:space.mask,limit:'检查圆形纹理及近纯色周围的矩形动态窗口，输出几何试做参数；实景物体和画框也可能满足条件，尚不识别任意形状、旋转或所有蒙版。'},
 {name:'抠像',status:space.cutout.length?'已生成复现遮罩':spatial?'未提取可靠人物':'尚未运行',evidence:space.cutout,limit:'新计算人物前景遮罩供复现，不证明原片用了抠像；当前不处理任意商品、动物或精细头发。'},
 {name:'跟踪',status:space.tracking.length?'有候选':spatial?'已检查，待确认':'尚未运行',evidence:space.tracking,limit:'比较文字与非文字局部特征的运动关系，并排除近似整体平移；同动也可能由实景文字或手动关键帧造成。'},
 {name:'调色',status:'待确认',evidence:[],limit:'当前仅测整体亮度；没有原片或色卡，不能反推出滤镜、LUT 与具体参数。'},
 {name:'叠加 / 位置缩放',status:visual.some(e=>e.kind==='scale')?'有候选':'待确认',evidence:visual.filter(e=>e.kind==='scale'),limit:'整体缩放也可能来自实拍运镜；不能据此确认画中画、混合模式或轨道层数。'},
 {name:'音效',status:audio?'已运行，待听辨':'可选，未运行',evidence:[],limit:audio?'声音模型输出已加入报告，仍不能确认现场声、后期音效和原音效库。':'点击“分析音效候选”检查真实音轨；视频静帧没有音效证据。'}]}
export function auditReport(rows){return '\n\n## 整片效果检查覆盖\n'+rows.map(r=>`${r.name}：${r.status}\n${r.limit}\n${r.evidence.map(e=>`${e.start.toFixed(2)}–${e.end.toFixed(2)} 秒 · ${e.title}\n${e.reason}\n${e.parameters}\n${e.steps.join('\n')}`).join('\n')}`).join('\n\n')}
export function renderEffectAudit(container,rows,onSeek){container.replaceChildren();for(const row of rows){const card=document.createElement('details'),summary=document.createElement('summary');summary.textContent=`${row.name} · ${row.status}${row.evidence.length?' · '+row.evidence.length+' 项':''}`;card.open=false;card.append(summary);const p=document.createElement('p');p.textContent=row.limit;card.append(p);const target={'字幕动画':'text-start','蒙版':'spatial-start','抠像':'spatial-start','跟踪':'spatial-start','音效':'browser-audio-events'}[row.name];if(target){const action=document.createElement('button');action.className='secondary';action.textContent=row.name==='音效'?'前往可选音效分析':'前往本项分析 / 重试';action.onclick=()=>{const button=document.getElementById(target);button.scrollIntoView({behavior:'smooth',block:'center'});button.focus()};card.append(action);}for(const item of row.evidence){const title=document.createElement('h4');title.textContent=`${item.start.toFixed(2)}–${item.end.toFixed(2)} 秒 · ${item.title}`;card.append(title);const button=document.createElement('button');button.className='secondary';button.textContent='播放此处核对';button.onclick=()=>onSeek(item.start);card.append(button);const teach=document.createElement('button');teach.className='secondary';teach.textContent='生成本项教学 MP4';teach.onclick=()=>document.dispatchEvent(new CustomEvent('teach-evidence-item',{detail:item}));card.append(teach);for(const content of [item.reason,item.parameters]){const p=document.createElement('p');p.textContent=content;card.append(p)}const list=document.createElement('ol');item.steps.forEach(s=>{const li=document.createElement('li');li.textContent=s;list.append(li)});card.append(list)}container.append(card)}}
